import os
import json
import base64
import secrets
from dataclasses import dataclass
from typing import Any, Dict, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeEncryptedPayload:
    encrypted_data_key: str
    iv: str
    ciphertext: str
    tag: str

    def to_json(self) -> str:
        return json.dumps(
            {
                "encrypted_data_key": self.encrypted_data_key,
                "iv": self.iv,
                "ciphertext": self.ciphertext,
                "tag": self.tag,
            }
        )

    @staticmethod
    def from_json(payload: Union[str, bytes]) -> "EnvelopeEncryptedPayload":
        if isinstance(payload, bytes):
            payload = payload.decode("utf-8")
        data = json.loads(payload)
        return EnvelopeEncryptedPayload(
            encrypted_data_key=data["encrypted_data_key"],
            iv=data["iv"],
            ciphertext=data["ciphertext"],
            tag=data["tag"],
        )


class AWSEnvelopeEncryptor:
    def __init__(self, kms_key_id: str, region_name: str = None):
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name or os.getenv("AWS_REGION"))

    @staticmethod
    def _b64encode(data: bytes) -> str:
        return base64.b64encode(data).decode("utf-8")

    @staticmethod
    def _b64decode(data: str) -> bytes:
        return base64.b64decode(data.encode("utf-8"))

    def encrypt(self, plaintext: Union[str, bytes]) -> str:
        if isinstance(plaintext, str):
            plaintext = plaintext.encode("utf-8")

        try:
            data_key_resp = self.kms.generate_data_key(KeyId=self.kms_key_id, KeySpec="AES_256")
            plaintext_data_key = data_key_resp["Plaintext"]
            encrypted_data_key = data_key_resp["CiphertextBlob"]

            iv = secrets.token_bytes(12)

            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            aesgcm = AESGCM(plaintext_data_key)
            ct_and_tag = aesgcm.encrypt(iv, plaintext, None)
            ciphertext = ct_and_tag[:-16]
            tag = ct_and_tag[-16:]

            payload = EnvelopeEncryptedPayload(
                encrypted_data_key=self._b64encode(encrypted_data_key),
                iv=self._b64encode(iv),
                ciphertext=self._b64encode(ciphertext),
                tag=self._b64encode(tag),
            )
            return payload.to_json()
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS envelope encryption failed: {e}") from e

    def decrypt(self, payload: Union[str, bytes, Dict[str, Any]]) -> bytes:
        if isinstance(payload, dict):
            payload = json.dumps(payload)
        envelope = EnvelopeEncryptedPayload.from_json(payload)

        try:
            decrypted_key_resp = self.kms.decrypt(
                CiphertextBlob=self._b64decode(envelope.encrypted_data_key)
            )
            plaintext_data_key = decrypted_key_resp["Plaintext"]

            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            aesgcm = AESGCM(plaintext_data_key)
            iv = self._b64decode(envelope.iv)
            ciphertext = self._b64decode(envelope.ciphertext)
            tag = self._b64decode(envelope.tag)
            return aesgcm.decrypt(iv, ciphertext + tag, None)
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS envelope decryption failed: {e}") from e


def encrypt(plaintext: Union[str, bytes], kms_key_id: str, region_name: str = None) -> str:
    return AWSEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name).encrypt(plaintext)


def decrypt(payload: Union[str, bytes, Dict[str, Any]], kms_key_id: str, region_name: str = None) -> bytes:
    return AWSEnvelopeEncryptor(kms_key_id=kms_key_id, region_name=region_name).decrypt(payload)
